First, let's create the Redux store configuration:

**`store.js`**
```javascript
import { configureStore } from '@reduxjs/toolkit';
import cartReducer from './cartSlice';

const store = configureStore({
  reducer: {
    cart: cartReducer,
  },
});

export default store;
```

Next, create the cart slice reducer:

**`cartSlice.js`**
```javascript
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  total: 0,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      state.items = [...state.items, action.payload];
      state.total += action.payload.price;
    },
    removeItem(state, action) {
      state.items = state.items.filter((item) => item.id!== action.payload.id);
      state.total -= action.payload.price;
    },
    resetCart(state) {
      state.items = [];
      state.total = 0;
    },
  },
});

export const { addItem, removeItem, resetCart } = cartSlice.actions;
export default cartSlice.reducer;
```

Now, let's create the Shopping Cart component:

**`ShoppingCart.js`**
```javascript
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem, resetCart } from './cartSlice';

const ShoppingCart = () => {
  const dispatch = useDispatch();
  const { items, total } = useSelector((state) => state.cart);

  const handleAddItem = (item) => {
    dispatch(addItem(item));
  };

  const handleRemoveItem = (item) => {
    dispatch(removeItem(item));
  };

  const handleResetCart = () => {
    dispatch(resetCart());
  };

  return (
    <div>
      <h2>Shopping Cart</h2>
      <ul>
        {items.map((item) => (
          <li key={item.id}>
            {item.name} x {item.quantity} = {item.price}
            <button onClick={() => handleRemoveItem(item)}>Remove</button>
          </li>
        ))}
      </ul>
      <p>Total: {total}</p>
      <button onClick={handleResetCart}>Reset Cart</button>
    </div>
  );
};

export default ShoppingCart;
```

